style.css:
@-moz-document domain("roblox.com") {
/* =========================================================
       VARIABLES
       ========================================================= */

    :root {
        --r20-sidebar-width: 220px;
        --r20-sidebar-bg: #191a1d;
        --r20-sidebar-border: #2b2d31;
        --r20-hover: #27292d;
        --r20-selected: #393b3f;
        --r20-text: #f2f2f2;
        --r20-muted: #bdbfc2;
        --r20-white: #ffffff;
    }


    /* =========================================================
       CURRENT ROBLOX SIDEBAR
       ========================================================= */

    #navigation,
    .rbx-left-col {
        width: var(--r20-sidebar-width) !important;
        min-width: var(--r20-sidebar-width) !important;
        max-width: var(--r20-sidebar-width) !important;

        background: var(--r20-sidebar-bg) !important;

        border-right: 1px solid var(--r20-sidebar-border) !important;

        box-shadow: none !important;

        overflow-x: hidden !important;
    }


    /* =========================================================
       SIDEBAR CONTENT
       ========================================================= */

    #navigation > div,
    .rbx-left-col > div {
        width: 100% !important;
        max-width: none !important;
    }

    #navigation ul,
    .rbx-left-col ul {
        width: 100% !important;

        margin: 0 !important;
        padding: 8px 0 !important;

        list-style: none !important;
    }


    /* =========================================================
       NAVIGATION ITEMS
       ========================================================= */

    #navigation li,
    .rbx-left-col li {
        width: 100% !important;

        margin: 0 !important;
        padding: 0 !important;

        list-style: none !important;
    }


    #navigation a,
    .rbx-left-col a {

        display: flex !important;

        align-items: center !important;

        box-sizing: border-box !important;

        width: 100% !important;

        min-height: 44px !important;

        padding: 10px 18px !important;

        margin: 0 !important;

        border: 0 !important;
        border-radius: 0 !important;

        background: transparent !important;

        color: var(--r20-text) !important;

        font-family:
            "Source Sans Pro",
            Arial,
            sans-serif !important;

        font-size: 15px !important;

        font-weight: 600 !important;

        line-height: 24px !important;

        text-decoration: none !important;

        transition:
            background-color .12s ease,
            color .12s ease !important;
    }


    /* =========================================================
       HOVER
       ========================================================= */

    #navigation a:hover,
    .rbx-left-col a:hover {

        background: var(--r20-hover) !important;

        color: var(--r20-white) !important;
    }


    /* =========================================================
       ACTIVE ITEM
       ========================================================= */

    #navigation a.active,
    #navigation a[aria-current="page"],
    .rbx-left-col a.active,
    .rbx-left-col a[aria-current="page"] {

        background: var(--r20-selected) !important;

        color: var(--r20-white) !important;

        font-weight: 700 !important;
    }


    /* =========================================================
       ICONS
       ========================================================= */

    #navigation svg,
    .rbx-left-col svg {

        width: 22px !important;
        height: 22px !important;

        min-width: 22px !important;

        margin-right: 14px !important;

        flex-shrink: 0 !important;
    }


    #navigation img,
    .rbx-left-col img {

        width: 22px !important;
        height: 22px !important;

        min-width: 22px !important;

        object-fit: contain !important;

        margin-right: 14px !important;

        flex-shrink: 0 !important;
    }


    /* =========================================================
       TEXT
       ========================================================= */

    #navigation span,
    #navigation a span,
    .rbx-left-col span,
    .rbx-left-col a span {

        color: inherit !important;

        font-family:
            "Source Sans Pro",
            Arial,
            sans-serif !important;

        font-size: 15px !important;

        font-weight: inherit !important;

        white-space: nowrap !important;
    }


    /* =========================================================
       BADGE COUNTS
       ========================================================= */

    #navigation .notification-count,
    #navigation .badge,
    #navigation .rbx-nav-notification-count,
    .rbx-left-col .notification-count,
    .rbx-left-col .badge {

        display: flex !important;

        align-items: center !important;
        justify-content: center !important;

        min-width: 22px !important;
        height: 22px !important;

        padding: 0 6px !important;

        margin-left: auto !important;

        border-radius: 11px !important;

        background: #ffffff !important;

        color: #393b3d !important;

        font-size: 12px !important;

        font-weight: 700 !important;

        line-height: 22px !important;
    }


    /* =========================================================
       PROFILE / USER AREA
       ========================================================= */

    #navigation .profile,
    #navigation .nav-profile,
    .rbx-left-col .profile,
    .rbx-left-col .nav-profile {

        margin-bottom: 4px !important;
    }


    /* User avatar */

    #navigation .avatar,
    #navigation .avatar-card,
    .rbx-left-col .avatar,
    .rbx-left-col .avatar-card {

        border-radius: 50% !important;

        overflow: hidden !important;
    }


    /* =========================================================
       DIVIDERS
       ========================================================= */

    #navigation hr,
    #navigation .divider,
    #navigation .rbx-divider,
    .rbx-left-col hr,
    .rbx-left-col .divider {

        height: 1px !important;

        margin: 8px 16px !important;

        padding: 0 !important;

        border: 0 !important;

        background: var(--r20-sidebar-border) !important;
    }


    /* =========================================================
       OLD-SCHOOL SECTION SPACING
       ========================================================= */

    #navigation .section,
    .rbx-left-col .section {

        margin: 0 !important;

        padding: 4px 0 !important;
    }


    /* =========================================================
       HIDE MODERN "MORE FUN FOR LESS ROBUX" CARD
       ========================================================= */

    #navigation .rbx-upgrade-now,
    .rbx-left-col .rbx-upgrade-now {

        display: none !important;
    }


    /* =========================================================
       HIDE MODERN EXTRA SIDEBAR ELEMENTS
       ========================================================= */

    #navigation .dynamic-ellipsis-item,
    #navigation .font-bold.small.text-nav,
    .rbx-left-col .dynamic-ellipsis-item,
    .rbx-left-col .font-bold.small.text-nav {

        display: none !important;
    }


    /* =========================================================
       BLOG PREVIEWS
       ========================================================= */

    #navigation .blog,
    .rbx-left-col .blog {

        background: transparent !important;

        padding: 8px 18px !important;
    }


    #navigation .blog a,
    .rbx-left-col .blog a {

        display: block !important;

        min-height: 0 !important;

        padding: 4px 0 !important;

        background: transparent !important;

        font-size: 12px !important;

        line-height: 13px !important;

        font-weight: 600 !important;
    }


    /* =========================================================
       OFFICIAL STORE / GIFT CARDS
       ========================================================= */

    #navigation .shop,
    #navigation .gift-card,
    .rbx-left-col .shop,
    .rbx-left-col .gift-card {

        margin-top: 4px !important;
    }


    /* =========================================================
       SCROLLBAR
       ========================================================= */

    #navigation::-webkit-scrollbar,
    .rbx-left-col::-webkit-scrollbar {

        width: 5px !important;
    }


    #navigation::-webkit-scrollbar-track,
    .rbx-left-col::-webkit-scrollbar-track {

        background: transparent !important;
    }


    #navigation::-webkit-scrollbar-thumb,
    .rbx-left-col::-webkit-scrollbar-thumb {

        background: #45474b !important;

        border-radius: 3px !important;
    }


    /* =========================================================
       MAIN CONTENT
       ========================================================= */

    #wrap {

        margin-left: var(--r20-sidebar-width) !important;
    }


    .rbx-body {

        padding-left: 0 !important;
    }


    /* =========================================================
       OLD 2020-STYLE FONT
       ========================================================= */

    #navigation,
    #navigation *,
    .rbx-left-col,
    .rbx-left-col * {

        font-family:
            "Source Sans Pro",
            Arial,
            sans-serif !important;
    }


    /* =========================================================
       REMOVE MODERN ROUNDED NAVIGATION
       ========================================================= */

    #navigation *,
    .rbx-left-col * {

        --border-radius-medium: 0px !important;
        --border-radius-large: 0px !important;
    }


    /* =========================================================
       MOBILE / SMALL SCREEN
       ========================================================= */

    @media (max-width: 700px) {

        #navigation,
        .rbx-left-col {

            width: 220px !important;
            min-width: 220px !important;
        }

        #wrap {

            margin-left: 220px !important;
        }
    }


    /* =========================================================
       DARK THEME CLEANUP
       ========================================================= */

    .dark-theme #navigation,
    .dark-theme .rbx-left-col {

        background: #191a1d !important;

        border-right-color: #2b2d31 !important;
    }


    .dark-theme #navigation a,
    .dark-theme .rbx-left-col a {

        color: #f2f2f2 !important;
    }


    .dark-theme #navigation a:hover,
    .dark-theme .rbx-left-col a:hover {

        background: #27292d !important;
    }


    .dark-theme #navigation a.active,
    .dark-theme .rbx-left-col a.active {

        background: #393b3f !important;
    }
}
